from ._tulis import Q, bab, kursus, latihan

# ---------------------------------------------------------------- 24 Payroll Staff
# Fakta diambil dari artikel Gadjian (rangkuman peraturan payroll), artikel Hukumonline (upah lembur), dan artikel DJP (TER PPh 21).
# Aturan ketenagakerjaan dan pajak berubah; angka harus dicek ulang ke peraturan terbaru sebelum dipakai untuk gaji sungguhan.
kursus(24, "Payroll Staff",
 bab(["Menjelaskan apa yang dikerjakan staf payroll dalam satu periode gaji.",
      "Menyebut komponen gaji menurut PP Pengupahan yang dikutip Gadjian.",
      "Menjelaskan bahwa upah tidak boleh di bawah upah minimum, dan pengecualiannya.",
      "Menjelaskan mengapa angka payroll harus bisa diperiksa dan dilindungi."],
  ("Pekerjaan staf payroll",
   "Staf payroll menghitung gaji karyawan tiap periode dengan benar dan tepat waktu: menjumlahkan upah dan tunjangan, menambahkan lembur bila ada, mengurangi potongan seperti iuran BPJS dan PPh 21, lalu menghasilkan slip gaji. Artikel Gadjian yang merangkum peraturan payroll di Indonesia menyebut pengusaha wajib memberikan bukti pembayaran yang merinci gaji, upah dibayar dalam rupiah, sesuai periode dan tanggal yang ditetapkan, dengan jangka waktu pembayaran tidak lebih dari satu bulan."),
  ("Komponen gaji dan upah minimum",
   "Menurut Gadjian yang mengutip PP Pengupahan Nomor 36 Tahun 2021 Pasal 7, gaji dapat terdiri dari upah tanpa tunjangan, upah pokok ditambah tunjangan tetap, upah pokok ditambah tunjangan tetap dan tidak tetap, atau upah pokok ditambah tunjangan tidak tetap. Bila ada tunjangan tetap, upah pokok minimal 75% dari gaji. Pengusaha dilarang membayar upah di bawah upah minimum (UMK atau UMP); ketentuan itu tidak berlaku untuk usaha mikro dan kecil, dan berlaku untuk karyawan tetap, kontrak, dan masa percobaan."),
  ("Data gaji itu rahasia",
   "Gaji, nomor rekening, dan potongan adalah data pribadi karyawan. Staf payroll hanya membuka data itu untuk keperluan menghitung dan membayar gaji, tidak membagikannya lewat grup obrolan, dan menyimpan berkas hitungan di tempat yang dilindungi. Dalam kursus ini semua latihan memakai karyawan rekaan; jangan memasukkan data gaji nyata siapa pun ke dalam tugas atau portofoliomu.")),
 bab(["Menghitung upah sejam dari upah sebulan.",
      "Menghitung upah lembur pada hari kerja biasa.",
      "Menyebut batas waktu kerja dan batas lembur.",
      "Menjelaskan kelipatan lembur pada hari libur."],
  ("Rumus lembur hari kerja",
   "Artikel Hukumonline menyebut upah sejam sama dengan 1/173 dikali upah sebulan. Pada hari kerja biasa, jam lembur pertama dibayar 1,5 kali upah sejam dan setiap jam berikutnya 2 kali upah sejam. Waktu kerja normal adalah 7 jam sehari dan 40 jam seminggu untuk enam hari kerja, atau 8 jam sehari dan 40 jam seminggu untuk lima hari kerja. Lembur hanya boleh maksimal 4 jam sehari dan 18 jam seminggu, dan memerlukan perintah pengusaha serta persetujuan pekerja secara tertulis atau melalui media digital."),
  ("Lembur pada hari libur",
   "Untuk hari istirahat mingguan atau libur resmi pada enam hari kerja, jam ke-1 sampai ke-7 dibayar 2 kali upah sejam, jam ke-8 dibayar 3 kali, dan jam ke-9 sampai ke-11 dibayar 4 kali. Pada lima hari kerja, jam ke-1 sampai ke-8 dibayar 2 kali, jam ke-9 dibayar 3 kali, dan jam ke-10 sampai ke-12 dibayar 4 kali. Upah harian dikonversi ke upah sebulan dengan dikali 25 untuk enam hari kerja atau dikali 21 untuk lima hari kerja. Bila perhitungan perusahaan lebih menguntungkan pekerja, perhitungan itu tetap berlaku.")),
 bab(["Menyebut persentase iuran BPJS Kesehatan untuk pemberi kerja dan karyawan.",
      "Menyebut persentase JHT, JP, dan JKM menurut Gadjian.",
      "Menjelaskan aturan THR.",
      "Menyebut jenis potongan gaji yang diperbolehkan."],
  ("Iuran BPJS",
   "Menurut Gadjian, iuran BPJS Kesehatan peserta penerima upah adalah 5% dari gaji per bulan: 4% ditanggung pemberi kerja dan 1% karyawan, dengan batas atas dasar perhitungan Rp12 juta. Untuk BPJS Ketenagakerjaan, Jaminan Hari Tua (JHT) 5,7% dengan 3,7% pemberi kerja dan 2% karyawan; Jaminan Pensiun (JP) 3% dengan 2% pemberi kerja dan 1% karyawan; Jaminan Kematian (JKM) 0,30% ditanggung pemberi kerja. Jaminan Kecelakaan Kerja ditanggung pemberi kerja dan persentasenya tidak tercantum di teks halaman itu."),
  ("THR dan potongan gaji",
   "THR menurut Permenaker 6 Tahun 2016 yang dikutip Gadjian: karyawan dengan masa kerja 12 bulan atau lebih menerima satu bulan upah, sedangkan masa kerja satu sampai kurang dari 12 bulan dibayar proporsional. THR dibayar paling lambat 7 hari sebelum hari raya, dan keterlambatan dikenai denda 5% dari jumlah THR. Potongan gaji yang diperbolehkan menurut PP Pengupahan Pasal 63 antara lain denda, ganti rugi, uang muka upah atau kasbon, sewa rumah atau barang perusahaan, cicilan utang karyawan, dan kelebihan pembayaran upah.")),
 bab(["Menjelaskan perhitungan biaya jabatan.",
      "Menyebut unsur PTKP untuk orang pribadi menurut Gadjian.",
      "Menjelaskan cara memakai TER pada masa Januari sampai November.",
      "Menyusun slip gaji rekaan dari awal sampai akhir."],
  ("Biaya jabatan, PTKP, dan TER",
   "Gadjian menyebut biaya jabatan 5% dari penghasilan bruto dengan batas Rp6.000.000 setahun atau Rp500.000 sebulan. PTKP menurut PMK 101/2016 adalah Rp54.000.000 untuk diri sendiri, tambahan Rp4.500.000 untuk wajib pajak kawin, dan Rp4.500.000 per tanggungan paling banyak tiga orang. Sejak Januari 2024 pemotongan PPh 21 bulanan memakai Tarif Efektif Rata-Rata (TER) berdasarkan PP 58 Tahun 2023: TER A untuk TK/0, TK/1, dan K/0; TER B untuk TK/2, TK/3, K/1, dan K/2; TER C untuk K/3. TER dipakai Januari sampai November dan dasarnya penghasilan bruto."),
  ("Masa Desember dan pegawai tidak tetap",
   "Artikel DJP menyebut pada masa Desember pemotong menghitung dengan tarif Pasal 17 ayat (1) huruf a UU PPh supaya total pemotongan setahun sesuai. Untuk pegawai tidak tetap dipakai TER harian: 0% bila penghasilan bruto harian sampai Rp450.000 dan 0,5% bila di atas Rp450.000 sampai Rp2.500.000. Halaman DJP lain menyebut tarif tiap kategori berkisar dari 0% untuk penghasilan bruto di bawah Rp5,4 juta per bulan sampai 34% untuk di atas Rp1,4 miliar per bulan.")),
 bab(["Menyusun slip gaji rekaan dari awal sampai akhir.",
      "Memeriksa bahwa total slip cocok dengan rekap biaya perusahaan.",
      "Menandai angka yang tidak diyakini dan menyebut sumbernya.",
      "Menjaga kerahasiaan data saat berbagi hasil kerja."],
  ("Menyusun slip gaji rekaan",
   "Urutan menyusun slip: tulis upah pokok dan tunjangan, tambahkan lembur dari rumus, jumlahkan menjadi penghasilan bruto, kurangi iuran BPJS bagian karyawan, hitung PPh 21 dengan kategori TER yang sesuai, lalu tulis gaji bersih. Selalu simpan sumber tiap persentase beserta tanggal pengambilannya, karena peraturan dapat berubah. Bila ada angka yang kamu tidak yakin, tandai di slip dan tanyakan kepada guru atau konsultan pajak sebelum dibagikan."),
  ("Memeriksa hasil sebelum dibagikan",
   "Setelah slip selesai, periksa tiga hal. Pertama, jumlah semua gaji bersih ditambah semua potongan harus sama dengan jumlah penghasilan bruto seluruh karyawan. Kedua, iuran BPJS bagian karyawan dan bagian pemberi kerja dijumlahkan terpisah agar biaya perusahaan jelas. Ketiga, minta orang lain memeriksa satu slip secara acak dari hitungan awal. Berkas hitungan hanya dibagikan kepada pihak yang berwenang, dan nama karyawan nyata tidak dipakai dalam latihan.")),
 {"title": "Simulasi payroll satu bulan untuk lima karyawan rekaan",
  "brief": "Buat simulasi payroll satu bulan untuk lima karyawan rekaan di usaha kecil rekaan. Setiap karyawan punya upah pokok, tunjangan, status PTKP, dan jam lembur yang berbeda. Hitung lembur dengan rumus 1/173, iuran BPJS bagian karyawan dan pemberi kerja, PPh 21 dengan TER, lalu susun slip gaji dan rekap total biaya perusahaan. Setiap persentase harus diberi sumber dan tanggal, dan bagian yang kamu tidak yakin ditandai.",
  "criteria": ["Lima karyawan rekaan dengan data upah, tunjangan, status PTKP, dan jam lembur.",
               "Perhitungan lembur memakai 1/173 dan kelipatan yang benar, lengkap dengan contoh hitungan.",
               "Iuran BPJS Kesehatan dan Ketenagakerjaan dihitung terpisah untuk pemberi kerja dan karyawan.",
               "PPh 21 dihitung dengan kategori TER yang sesuai dan sumber tarifnya disebut.",
               "Slip gaji tiap karyawan memuat rincian dan gaji bersih yang cocok dengan hitungan.",
               "Rekap biaya perusahaan (gaji, iuran pemberi kerja) cocok dengan jumlah semua slip.",
               "Bagian yang tidak diyakini ditandai, dan daftar sumber dengan tanggal dicantumkan.",
               "Tidak ada data pribadi nyata yang dipakai."]},
 [
 Q(2, "A", "Menurut Gadjian, upah dibayar dalam:", "Rupiah", "Dolar Amerika", "Barang dagangan perusahaan", "Mata uang yang dipilih pemberi kerja bebas", "a", "PP Pengupahan mensyaratkan upah dibayar dalam rupiah."),
 Q(2, "K", "Pada gaji berupa upah pokok ditambah tunjangan tetap, upah pokok minimal:", "75% dari gaji", "50% dari gaji", "25% dari gaji", "100% dari tunjangan", "a", "Gadjian mengutip PP 36/2021 Pasal 7: upah pokok minimal 75% dari gaji."),
 Q(2, "K", "Ketentuan larangan membayar di bawah upah minimum tidak berlaku untuk:", "Usaha mikro dan kecil", "Karyawan kontrak", "Karyawan masa percobaan", "Karyawan tetap", "a", "Gadjian: tidak berlaku untuk usaha mikro dan kecil, tetapi berlaku untuk karyawan tetap, kontrak, dan probation."),
 Q(2, "K", "Jangka waktu pembayaran upah menurut Gadjian:", "Tidak lebih dari satu bulan", "Boleh sampai tiga bulan", "Harus setiap hari", "Terserah karyawan saja", "a", "PP Pengupahan: jangka waktu pembayaran tidak boleh lebih dari satu bulan."),
 Q(2, "A", "Bukti pembayaran gaji yang diberikan kepada karyawan sebaiknya:", "Merinci komponen gaji dan potongan", "Hanya menyebut total saja", "Disimpan oleh pemberi kerja tanpa diberikan", "Berisi gaji karyawan lain sebagai pembanding", "a", "Pengusaha wajib memberikan bukti pembayaran yang merinci gaji."),
 Q(2, "K", "Data gaji karyawan sebaiknya diperlakukan sebagai:", "Data pribadi yang hanya dibuka untuk keperluan menghitung dan membayar gaji", "Bahan obrolan di grup kantor", "Data umum yang boleh ditempel di papan pengumuman", "Informasi yang boleh dibagikan kepada siapa saja yang bertanya", "a", "Gaji dan rekening adalah data pribadi sehingga akses harus dibatasi."),
 Q(2, "K", "Gaji tersusun dari upah pokok dan tunjangan tidak tetap saja. Upah pokok yang harus memenuhi upah minimum adalah:", "Upah pokok", "Tunjangan tidak tetap", "Seluruh THR", "Lembur", "a", "Gadjian: pada upah pokok ditambah tunjangan tidak tetap, upah pokok minimal sama dengan upah minimum."),
 Q(3, "K", "Upah sejam dihitung dari:", "1/173 dikali upah sebulan", "1/30 dikali upah sebulan", "Upah sebulan dibagi 8", "Upah sebulan dikali 173", "a", "Hukumonline dan Gadjian menyebut rumus 1/173 dikali upah sebulan."),
 Q(3, "K", "Upah sebulan Rp1.730.000 membuat upah sejam sebesar:", "Rp10.000", "Rp1.000", "Rp100.000", "Rp173.000", "a", "1.730.000 dibagi 173 sama dengan 10.000."),
 Q(3, "K", "Pada hari kerja biasa, jam lembur pertama dibayar:", "1,5 kali upah sejam", "2 kali upah sejam", "3 kali upah sejam", "4 kali upah sejam", "a", "Hukumonline: jam lembur pertama 1,5 kali, jam berikutnya 2 kali."),
 Q(3, "K", "Upah sejam Rp10.000. Lembur 3 jam pada hari kerja biasa menghasilkan:", "Rp55.000", "Rp30.000", "Rp60.000", "Rp45.000", "a", "1,5 x 10.000 = 15.000 untuk jam pertama, ditambah 2 x 10.000 x 2 jam = 40.000; total 55.000."),
 Q(3, "K", "Batas lembur menurut Hukumonline:", "Maksimal 4 jam sehari dan 18 jam seminggu", "Maksimal 8 jam sehari tanpa batas mingguan", "Maksimal 2 jam sehari dan 10 jam seminggu", "Tidak ada batas", "a", "Lembur dibatasi 4 jam sehari dan 18 jam seminggu."),
 Q(3, "K", "Pada enam hari kerja, lembur hari libur jam ke-8 dibayar:", "3 kali upah sejam", "2 kali upah sejam", "4 kali upah sejam", "1,5 kali upah sejam", "a", "Jam ke-1 sampai ke-7 dibayar 2 kali, jam ke-8 3 kali, jam ke-9 sampai ke-11 4 kali."),
 Q(3, "A", "Lembur memerlukan:", "Perintah pengusaha dan persetujuan pekerja", "Keputusan pekerja saja", "Keputusan pengusaha saja tanpa persetujuan", "Izin dari pelanggan", "a", "Hukumonline: lembur memerlukan perintah pengusaha dan persetujuan pekerja secara tertulis atau digital."),
 Q(4, "A", "Iuran BPJS Kesehatan total 5% dari gaji. Bagian karyawan adalah:", "1%", "4%", "5%", "0%", "a", "Gadjian: pemberi kerja 4% dan karyawan 1%."),
 Q(4, "K", "Iuran JHT total 5,7%. Bagian karyawan adalah:", "2%", "3,7%", "5,7%", "1%", "a", "Gadjian: pemberi kerja 3,7% dan karyawan 2%."),
 Q(4, "K", "Iuran Jaminan Pensiun (JP) bagian karyawan adalah:", "1%", "2%", "3%", "0,30%", "a", "Gadjian: JP 3% dengan 2% pemberi kerja dan 1% karyawan."),
 Q(4, "K", "Gaji Rp5.000.000. Potongan BPJS Kesehatan (1%) ditambah JHT (2%) ditambah JP (1%) bagian karyawan sebesar:", "Rp200.000", "Rp150.000", "Rp250.000", "Rp400.000", "a", "4% dari 5.000.000 adalah 200.000."),
 Q(4, "K", "THR dibayar paling lambat:", "7 hari sebelum hari raya", "Pada hari raya", "7 hari setelah hari raya", "Sebulan setelah hari raya", "a", "Gadjian mengutip Permenaker 6/2016."),
 Q(4, "K", "Denda keterlambatan pembayaran THR menurut Gadjian:", "5% dari jumlah THR", "10% dari gaji tahunan", "1% per hari", "Tidak ada denda", "a", "Keterlambatan dikenai denda 5% dari jumlah THR."),
 Q(4, "K", "Potongan gaji yang diperbolehkan menurut PP Pengupahan Pasal 63 antara lain:", "Cicilan utang karyawan yang disepakati", "Biaya liburan pemilik usaha", "Pajak pribadi atasan", "Biaya iklan perusahaan", "a", "Pasal 63 menyebut denda, ganti rugi, kasbon, sewa, utang atau cicilan, dan kelebihan pembayaran upah."),
 Q(5, "K", "Biaya jabatan dihitung:", "5% dari penghasilan bruto dengan batas Rp500.000 sebulan", "10% dari gaji bersih tanpa batas", "Rp500.000 tetap untuk semua pegawai", "5% dari laba perusahaan", "a", "Gadjian: 5% dari bruto, maksimal Rp6.000.000 setahun atau Rp500.000 sebulan."),
 Q(5, "K", "Tambahan PTKP untuk setiap tanggungan menurut Gadjian:", "Rp4.500.000, paling banyak tiga orang", "Rp54.000.000 tanpa batas", "Rp1.000.000 untuk satu orang", "Tidak ada tambahan", "a", "PMK 101/2016 yang dikutip Gadjian."),
 Q(5, "K", "Pegawai berstatus K/2 memakai kategori TER:", "TER B", "TER A", "TER C", "Tidak memakai TER", "a", "TER B untuk TK/2, TK/3, K/1, dan K/2."),
 Q(5, "K", "TER dipakai pada masa pajak:", "Januari sampai November", "Hanya Desember", "Hanya Januari", "Tidak pernah dipakai", "a", "Artikel DJP: Desember dihitung ulang dengan tarif Pasal 17."),
 Q(5, "K", "Dasar penghitungan PPh 21 dengan TER adalah:", "Penghasilan bruto", "Gaji bersih setelah biaya jabatan", "Laba perusahaan", "Jumlah tanggungan saja", "a", "Artikel DJP: TER tidak memperhitungkan biaya jabatan atau iuran pensiun."),
 Q(5, "K", "Persentase iuran dalam slip yang kamu tidak yakin sumbernya sebaiknya:", "Ditandai dan diperiksa ke sumber resmi sebelum dipakai", "Dipakai saja karena kemungkinan benar", "Diganti angka yang mudah dihitung", "Dihapus tanpa catatan", "a", "Aturan ketenagakerjaan dan pajak berubah sehingga angka perlu diverifikasi."),
 Q(5, "K", "Total biaya perusahaan untuk satu karyawan terdiri dari:", "Gaji dan iuran bagian pemberi kerja", "Hanya gaji bersih", "Hanya PPh 21", "Hanya iuran bagian karyawan", "a", "Perusahaan menanggung gaji dan iuran bagian pemberi kerja seperti BPJS."),
 ],
 sumber=[("Gadjian: Rangkuman Peraturan Perhitungan Payroll Karyawan Indonesia", "https://www.gadjian.com/blog/2022/10/14/peraturan-perhitungan-payroll-gaji"),
         ("Hukumonline: Cara Menghitung Upah Lembur", "https://www.hukumonline.com/klinik/a/hitung-upah-lembur-lt4b7e3965556d3"),
         ("DJP: Yuk, Ta'aruf dengan TER (25 Januari 2024)", "https://pajak.go.id/id/artikel/yuk-taaruf-dengan-ter"),
         ("DJP: Penghitungan PPh Pasal 21 dengan TER", "https://www.pajak.go.id/en/node/107937")])
latihan(24,
 ["Tulis urutan kerja payroll dari data absensi sampai slip gaji dalam enam langkah.",
  "Hitung 75% dari tiga contoh gaji untuk memeriksa batas upah pokok.",
  "Tulis tiga aturan menjaga kerahasiaan data gaji yang akan kamu pegang."],
 ["Hitung upah sejam untuk tiga contoh upah sebulan dengan rumus 1/173.",
  "Hitung lembur 1, 2, dan 3 jam pada hari kerja biasa untuk satu contoh upah.",
  "Buat tabel kelipatan lembur hari libur untuk enam hari kerja dan lima hari kerja."],
 ["Hitung iuran BPJS bagian karyawan untuk gaji Rp4.000.000 dan Rp8.000.000.",
  "Tulis aturan THR dengan kata-katamu dan beri satu contoh masa kerja 12 bulan.",
  "Daftar lima potongan gaji yang diperbolehkan dan satu yang tidak boleh kamu tambahkan sendiri."],
 ["Hitung biaya jabatan bulanan untuk tiga contoh gaji bruto.",
  "Tentukan kategori TER untuk lima status PTKP berbeda.",
  "Susun satu slip gaji rekaan lengkap dan minta temanmu memeriksa hitungannya."])
